(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-966":{scenario:{company:"Aquaville Urban Water",supervisor:{name:"Đỗ Văn Lâm",role:{vi:"Trưởng phòng Giảm thất thoát nước",en:"Non-revenue Water Manager"}},ref_code:"NRW-2610",title:{vi:"Tách đúng thất thoát. Giảm đúng chỗ rò.",en:"Split losses right. Fix real leaks."},brief:{vi:"Bạn lập cân bằng nước tháng 10 theo khung IWA cho vùng đồng hồ DMA-07, hồ sơ NRW-2610. Nước vào hệ thống 152400 m3; tiêu thụ hợp pháp có hóa đơn 118900 m3; hợp pháp không hóa đơn (chữa cháy, súc xả ống) 1600 m3; đồng hồ khách hàng đo thiếu ước tính 4300 m3; sử dụng trái phép 1200 m3. Sửa phân loại khoản đồng hồ đo thiếu và lượng thất thoát thực trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are building the October IWA water balance for district metered area DMA-07, file NRW-2610. System input volume 152400 m3; billed authorized consumption 118900 m3; unbilled authorized (firefighting, mains flushing) 1600 m3; estimated customer meter under-registration 4300 m3; unauthorized consumption 1200 m3. Correct the category of meter under-registration and the real losses in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Cân bằng nước IWA đã duyệt · NRW-2610",en:"Approved IWA water balance · NRW-2610"},fields:[{id:"METER_UR",label:{vi:"Phân loại khoản đồng hồ đo thiếu",en:"Meter under-registration category"},initial:"REAL-LOSS",expected:"APPARENT-LOSS",choices:["REAL-LOSS","APPARENT-LOSS","UNBILLED-AUTH"],reference:"Bảng cân bằng nước IWA",hint:{vi:"Nước đã đến tay khách hàng nhưng không được ghi nhận đủ là thất thoát thương mại, không phải rò rỉ vật lý.",en:"Water that reached the customer but was not fully recorded is a commercial loss, not a physical leak."}},{id:"REAL_LOSS",label:{vi:"Thất thoát thực tháng 10 (m3)",en:"October real losses (m3)"},initial:"30700",expected:"26400",reference:"Bảng tính thất thoát DMA-07",ref_value:{vi:"Vào 152400; có hóa đơn 118900; không hóa đơn 1600; đo thiếu 4300; trái phép 1200 (m3)",en:"Input 152400; billed 118900; unbilled 1600; meter error 4300; unauthorized 1200 (m3)"},hint:{vi:"Trừ đủ cả hai khoản thất thoát biểu kiến trước khi kết luận lượng rò rỉ vật lý.",en:"Deduct both apparent loss components before concluding the physical leakage volume."}}],sop32:{vi:"Thất thoát thực = nước vào hệ thống - tiêu thụ hợp pháp có hóa đơn - tiêu thụ hợp pháp không hóa đơn - thất thoát biểu kiến (đồng hồ đo thiếu + sử dụng trái phép), theo cân bằng nước IWA.",en:"Real losses = system input volume - billed authorized - unbilled authorized - apparent losses (meter under-registration + unauthorized use), per the IWA water balance."},context:{label:"SCADA / NRW-2610",metrics:[{label:{vi:"Nước vào DMA-07",en:"DMA-07 system input"},value:"152,400 m3"},{label:{vi:"Có hóa đơn",en:"Billed authorized"},value:"118,900 m3"},{label:{vi:"Lưu lượng đêm nhỏ nhất",en:"Minimum night flow"},value:"38 m3/h"}]},crisis:{vi:"Phó giám đốc nhắn: “Chuyển 8000 m3 sang mục súc xả ống cho tỷ lệ thất thoát quý này đạt chỉ tiêu, thưởng cả phòng phụ thuộc vào đó. Đoàn kiểm tra của tỉnh chỉ xem tổng thôi.”",en:"The deputy director messages you: “Move 8000 m3 into mains flushing so this quarter's loss rate meets the target, the whole team's bonus depends on it. The provincial inspectors only look at the totals.”"},options:{safe:{vi:"Giữ cân bằng nước đúng, từ chối ghi khống súc xả và báo giám đốc bằng văn bản; đề xuất dò rò chủ động, quản lý áp lực và thay đồng hồ cũ để giảm thất thoát thật.",en:"Keep the true water balance, refuse to inflate flushing volumes and inform the director in writing; propose active leak detection, pressure management and old meter replacement."},shortcut:{vi:"Ghi thêm 8000 m3 súc xả ống để đạt chỉ tiêu quý, quý sau điều chỉnh lại cho khớp.",en:"Record an extra 8000 m3 of flushing to meet the quarterly target and reconcile next quarter."},wait:{vi:"Không nộp báo cáo, chờ ban giám đốc tự quyết định số liệu.",en:"Hold the report and wait for management to decide the figures."}},questions:{vi:["Vì sao đồng hồ đo thiếu là thất thoát biểu kiến? Phân loại sai ảnh hưởng thế nào tới kế hoạch dò rò?","Trình bày cách tính thất thoát thực 26400 m3 và rủi ro pháp lý, uy tín nếu ghi khống tiêu thụ không hóa đơn."],en:["Why is meter under-registration an apparent loss? How does misclassifying it affect the leak detection plan?","Explain how you derived real losses and the legal and reputational risk of inflating unbilled consumption."]},hints:{vi:["Xem kết quả kiểm định đồng hồ và nhật ký kiểm tra trước khi xếp từng khoản vào cân bằng nước.","Trừ lần lượt từng thành phần theo SOP mục 3.2, đừng bỏ sót khoản nào của thất thoát biểu kiến.","Đọc lại SOP mục 4.2: số liệu cân bằng nước không được điều chỉnh vì chỉ tiêu; báo cáo áp lực bằng văn bản."],en:["Check the meter test and inspection log before placing each item in the water balance.","Subtract each component in turn per SOP 3.2 and do not miss any apparent loss item.","Re-read SOP 4.2: water balance figures must never be adjusted to meet targets; report pressure in writing."]},terminal:{system:"scada-dma",settable:["METER_UR","REAL_LOSS"],commands:[{cmd:"flow dma-07",out:{vi:"Nước vào DMA-07 tháng 10/2026: 152400 m3. Lưu lượng đêm nhỏ nhất 38 m3/h lúc 02:30, tăng 6 m3/h so với tháng 9.",en:"DMA-07 input in October 2026: 152400 m3. Minimum night flow 38 m3/h at 02:30, up 6 m3/h from September."}},{cmd:"billing summary",out:{vi:"Tiêu thụ có hóa đơn: 118900 m3. Hợp pháp không hóa đơn (chữa cháy, súc xả ống): 1600 m3.",en:"Billed authorized: 118900 m3. Unbilled authorized (firefighting, mains flushing): 1600 m3."}},{cmd:"meter test",out:{vi:"Kiểm định mẫu 200 đồng hồ khách hàng trên 10 năm tuổi: phần lớn chạy chậm ở lưu lượng thấp, ước tính đo thiếu 4300 m3.",en:"Sample test of 200 customer meters older than 10 years: most under-read at low flow, estimated under-registration 4300 m3."}},{cmd:"cat inspection.log",out:{vi:"Phát hiện 14 đấu nối trái phép tại tổ 5 và tổ 9, ước tính sử dụng 1200 m3.",en:"Found 14 illegal connections in blocks 5 and 9, estimated use 1200 m3."}},{cmd:"pressure log",out:{vi:"Áp lực ban đêm tại điểm áp lực trung bình vùng 3.8 bar, cao hơn mức mục tiêu 2.5 bar.",en:"Night pressure at the average zone point is 3.8 bar, above the 2.5 bar target."}}]}},learning:{summary:{vi:"Kỹ sư cấp thoát nước đô thị thiết kế, vận hành và tối ưu mạng lưới cấp nước, thoát nước mưa và nước thải: tính thủy lực, phân vùng tách mạng (DMA), giảm thất thoát, bảo đảm chất lượng nước và chống ngập. Nghề đòi hỏi vững thủy lực, dữ liệu SCADA, GIS và tính trung thực trong số liệu phục vụ cộng đồng.",en:"An urban water supply and drainage engineer designs, operates and optimizes water distribution, stormwater and sewer networks: hydraulic analysis, district metered areas (DMA), loss reduction, water quality and flood control. The role requires solid hydraulics, SCADA data, GIS skills and honest data that serves the public."},responsibilities:{vi:["Lập mô hình thủy lực, kiểm tra áp lực, lưu lượng và kích thước đường ống cấp, thoát nước.","Thiết lập và theo dõi vùng DMA, phân tích lưu lượng đêm nhỏ nhất để khoanh vùng rò rỉ.","Lập cân bằng nước IWA, tính NRW, thất thoát thực, thất thoát biểu kiến và chỉ số ILI.","Giám sát chất lượng nước tại điểm cuối mạng và phối hợp xử lý sự cố vỡ ống, ngập úng.","Lập kế hoạch cải tạo, thay ống và đồng hồ, quản lý áp lực và báo cáo cơ quan quản lý."],en:["Build hydraulic models and check pressure, flow and pipe sizes for supply and drainage networks.","Set up and monitor DMAs and analyze minimum night flow to locate leaks.","Prepare the IWA water balance: NRW, real losses, apparent losses and the ILI.","Monitor water quality at network extremities and coordinate response to bursts and flooding.","Plan pipe and meter renewal, pressure management and reporting to regulators."]},competencies:[{name:{vi:"Thủy lực mạng lưới",en:"Network hydraulics"},desc:{vi:"Tính tổn thất áp lực, mô phỏng mạng và chọn đường kính, bơm, van phù hợp.",en:"Compute head losses, simulate networks and select suitable pipes, pumps and valves."}},{name:{vi:"Quản lý thất thoát",en:"Water loss management"},desc:{vi:"Áp dụng cân bằng nước IWA, phân tích MNF, dò rò chủ động và quản lý áp lực.",en:"Apply the IWA water balance, MNF analysis, active leak detection and pressure management."}},{name:{vi:"Dữ liệu SCADA & GIS",en:"SCADA & GIS data"},desc:{vi:"Khai thác dữ liệu đồng hồ tổng, logger áp lực và bản đồ mạng để ra quyết định.",en:"Use bulk meters, pressure loggers and network maps to drive decisions."}},{name:{vi:"Chất lượng nước & môi trường",en:"Water quality & environment"},desc:{vi:"Theo dõi clo dư, độ đục và tuân thủ quy chuẩn nước sạch, nước thải.",en:"Track residual chlorine, turbidity and compliance with drinking water and effluent standards."}},{name:{vi:"Trung thực & phục vụ cộng đồng",en:"Integrity & public service"},desc:{vi:"Báo cáo đúng số liệu thất thoát, không làm đẹp chỉ tiêu, ưu tiên an toàn người dùng nước.",en:"Report losses truthfully, never dress up targets and put water users' safety first."}}],knowledge:{vi:["Khung cân bằng nước IWA: tiêu thụ hợp pháp, thất thoát biểu kiến, thất thoát thực và nước không doanh thu (NRW).","Chỉ số ILI = thất thoát thực hằng năm hiện tại / thất thoát thực tối thiểu không tránh được (UARL).","QCVN 01-1:2018/BYT về chất lượng nước sạch sử dụng cho mục đích sinh hoạt.","Nghị định 117/2007/NĐ-CP về sản xuất, cung cấp và tiêu thụ nước sạch; Nghị định 80/2014/NĐ-CP về thoát nước và xử lý nước thải.","TCVN 13606:2023 về thiết kế mạng lưới đường ống và công trình cấp nước; TCVN 7957 về mạng lưới thoát nước bên ngoài."],en:["The IWA water balance: authorized consumption, apparent losses, real losses and non-revenue water (NRW).","ILI = current annual real losses / unavoidable annual real losses (UARL).","QCVN 01-1:2018/BYT on domestic drinking water quality.","Decree 117/2007/ND-CP on clean water production, supply and consumption; Decree 80/2014/ND-CP on drainage and wastewater treatment.","TCVN 13606:2023 on water supply network and facility design; TCVN 7957 on external drainage networks."]},tools:["SCADA và đồng hồ tổng DMA","Phần mềm mô hình thủy lực (EPANET)","Thiết bị dò rò âm học và tương quan","GIS mạng lưới (QGIS)","Logger áp lực và lưu lượng","Phần mềm mô phỏng thoát nước (SWMM)"],kpis:{vi:["Tỷ lệ nước không doanh thu NRW (%).","Thất thoát thực tính theo lít/đấu nối/ngày hoặc chỉ số ILI.","Thời gian trung bình khắc phục sự cố vỡ ống.","Tỷ lệ mẫu nước đạt quy chuẩn tại điểm cuối mạng."],en:["Non-revenue water rate NRW (%).","Real losses in liters per connection per day or ILI.","Average time to repair pipe bursts.","Share of water samples compliant at network extremities."]},day:[{time:"07:30",vi:"Xem lưu lượng đêm nhỏ nhất của các DMA, đánh dấu vùng tăng bất thường.",en:"Review minimum night flows across DMAs and flag abnormal increases."},{time:"09:00",vi:"Cử tổ dò rò theo vùng nghi vấn, kiểm tra kết quả tương quan âm học.",en:"Dispatch leak crews to suspect zones and review correlator results."},{time:"11:00",vi:"Hiệu chỉnh mô hình thủy lực với số liệu logger áp lực mới.",en:"Calibrate the hydraulic model with new pressure logger data."},{time:"14:00",vi:"Lập cân bằng nước tháng, đối chiếu số liệu hóa đơn và kiểm định đồng hồ.",en:"Prepare the monthly water balance, reconciling billing and meter test data."},{time:"16:30",vi:"Họp kế hoạch thay ống, van giảm áp và báo cáo lãnh đạo.",en:"Plan pipe and pressure valve renewal and report to management."}],mistakes:{vi:["Xếp đồng hồ đo thiếu vào thất thoát thực, dẫn tới dò rò sai chỗ và lãng phí nguồn lực.","Chỉ báo cáo tỷ lệ NRW theo phần trăm, bỏ qua chỉ số theo đấu nối hoặc ILI.","Duy trì áp lực đêm quá cao, làm tăng rò rỉ và tần suất vỡ ống."],en:["Classing meter under-registration as real loss, sending crews to the wrong place and wasting resources.","Reporting NRW only as a percentage and ignoring per-connection indicators or ILI.","Keeping night pressure too high, which raises leakage and burst frequency."]},career:[{vi:"Kỹ thuật viên vận hành mạng cấp nước",en:"Water network technician"},{vi:"Kỹ sư cấp thoát nước",en:"Water supply and drainage engineer"},{vi:"Trưởng nhóm giảm thất thoát / quy hoạch mạng lưới",en:"NRW or network planning lead"},{vi:"Giám đốc kỹ thuật công ty cấp thoát nước",en:"Technical director of a water utility"}],glossary:[{term:"NRW",vi:"Nước không doanh thu: lượng nước vào hệ thống trừ tiêu thụ hợp pháp có hóa đơn.",en:"Non-revenue water: system input volume minus billed authorized consumption."},{term:"DMA",vi:"Vùng đồng hồ tổng: khu vực mạng được cô lập, đo lưu lượng vào ra để theo dõi thất thoát.",en:"District metered area: an isolated network zone with metered inflows to track losses."},{term:"MNF",vi:"Lưu lượng đêm nhỏ nhất, thường lúc 2-4 giờ sáng, phản ánh rõ nhất lượng rò rỉ.",en:"Minimum night flow, usually at 2-4 am, the clearest indicator of leakage."},{term:"Apparent loss",vi:"Thất thoát biểu kiến: nước đã dùng nhưng không được ghi nhận đúng do đồng hồ sai hoặc dùng trái phép.",en:"Water used but not correctly recorded due to meter error or unauthorized use."},{term:"ILI",vi:"Chỉ số rò rỉ hạ tầng: tỷ số giữa thất thoát thực hiện tại và mức tối thiểu không tránh được.",en:"Infrastructure leakage index: current real losses divided by the unavoidable minimum."}],quiz:[{q:{vi:"Đồng hồ khách hàng chạy chậm ở lưu lượng thấp thuộc thành phần nào trong cân bằng nước IWA?",en:"Customer meters under-reading at low flow belong to which IWA water balance component?"},options:{vi:["Thất thoát thực","Thất thoát biểu kiến","Tiêu thụ hợp pháp không hóa đơn","Tiêu thụ có hóa đơn"],en:["Real losses","Apparent losses","Unbilled authorized consumption","Billed consumption"]},answer:1,explain:{vi:"Sai số đồng hồ và sử dụng trái phép là thất thoát biểu kiến, không phải rò rỉ vật lý.",en:"Meter inaccuracy and unauthorized use are apparent losses, not physical leakage."}},{q:{vi:"Nước vào 100000 m3, có hóa đơn 78000 m3, hợp pháp không hóa đơn 1000 m3. NRW là bao nhiêu?",en:"Input 100000 m3, billed authorized 78000 m3, unbilled authorized 1000 m3. What is NRW?"},options:{vi:["21000 m3","79000 m3","22000 m3","23000 m3"],en:["21000 m3","79000 m3","22000 m3","23000 m3"]},answer:2,explain:{vi:"NRW = nước vào - tiêu thụ có hóa đơn = 100000 - 78000 = 22000 m3; NRW gồm cả tiêu thụ không hóa đơn.",en:"NRW = input - billed authorized = 100000 - 78000 = 22000 m3; it includes unbilled authorized use."}},{q:{vi:"Lãnh đạo yêu cầu ghi khống lượng súc xả ống để đạt chỉ tiêu thất thoát. Bạn làm gì?",en:"Management asks you to inflate mains flushing volumes to meet the loss target. What do you do?"},options:{vi:["Từ chối, giữ số liệu đúng, báo cáo bằng văn bản và đề xuất giải pháp giảm rò thật","Làm theo vì chỉ ảnh hưởng nội bộ","Ghi một nửa cho an toàn","Nghỉ phép để tránh"],en:["Refuse, keep true data, report in writing and propose real leak reduction","Comply since it is internal only","Record half to be safe","Take leave to avoid it"]},answer:0,explain:{vi:"Số liệu cân bằng nước là cơ sở quản lý và báo cáo nhà nước; làm sai là vi phạm và che giấu rò rỉ thật.",en:"Water balance data underpins management and official reporting; falsifying it is a violation and hides real leaks."}},{q:{vi:"Vì sao lưu lượng đêm nhỏ nhất (MNF) quan trọng trong dò rò?",en:"Why is minimum night flow (MNF) important for leak detection?"},options:{vi:["Vì giá nước ban đêm thấp","Vì áp lực ban đêm thấp nhất","Vì đồng hồ chính xác hơn ban đêm","Vì tiêu thụ hợp pháp thấp nhất nên rò rỉ chiếm tỷ trọng lớn nhất"],en:["Night tariffs are lower","Night pressure is lowest","Meters are more accurate at night","Legitimate use is lowest so leakage dominates the flow"]},answer:3,explain:{vi:"Ban đêm tiêu thụ hợp pháp thấp nhất nên phần lớn lưu lượng là rò rỉ; áp lực đêm thực tế lại cao.",en:"At night legitimate use is lowest so most flow is leakage, while night pressure is actually high."}}],tools_en:["SCADA and DMA bulk meters","Hydraulic modeling software (EPANET)","Acoustic leak detectors and correlators","Network GIS (QGIS)","Pressure and flow loggers","Drainage simulation software (SWMM)"]}}})})(window.KKR);
